'use client';

import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { startAssessment, submitAssessment } from '../../services/api';
import QuestionCard from '../../components/Assessment/QuestionCard';
import ProgressBar from '../../components/Assessment/ProgressBar';

export default function AssessmentPage() {
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const [questions, setQuestions] = useState([]);
    const [currentPage, setCurrentPage] = useState(0);
    const [answers, setAnswers] = useState([]); // Array of { qId, answer }
    const [setId, setSetId] = useState(null);
    const [isCompleted, setIsCompleted] = useState(false);
    const isSubmitting = useRef(false);

    const QUESTIONS_PER_PAGE = 10;

    // Temporary User ID generator or retrieval
    const getUserId = () => {
        if (typeof window === 'undefined') return null;
        let uid = localStorage.getItem('disc_user_id');
        if (!uid) {
            uid = 'user_' + Math.random().toString(36).substr(2, 9);
            localStorage.setItem('disc_user_id', uid);
        }
        return uid;
    };

    useEffect(() => {
        const fetchQuestions = async () => {
            try {
                const userId = getUserId();
                const data = await startAssessment(userId);
                if (data && data.questions) {
                    setQuestions(data.questions);
                    setSetId(data.setId);
                }
            } catch (error) {
                console.error("Failed to load questions", error);
            } finally {
                setLoading(false);
            }
        };
        fetchQuestions();
    }, []);

    // Redirect effect when assessment is completed
    useEffect(() => {
        if (isCompleted) {
            console.log('Assessment completed, redirecting to results...');
            const timer = setTimeout(() => {
                window.location.href = '/results';
            }, 500);
            return () => clearTimeout(timer);
        }
    }, [isCompleted]);

    const handleAnswer = (qId, type, isSelected) => {
        // If isSelected is true, we add/update the answer with the type.
        // If isSelected is false (unchecking), we should remove it or set to null?
        // Backend handles "D", "I", "S", "C". If we send null/undefined it might not count.
        // Let's assume we treat "Not Me" as simply not sending a "D/I/S/C" answer for that question,
        // OR we send it but logic doesn't count it.
        // The previous logic was: `scores[ans.answer]++`. So we need to ensure we only send the TYPE if "Describes Me".
        // But for completeness, we might want to record "Not Me". 
        // Let's stick to the previous plan: "Describes Me" -> type. "Not Me" -> null (which won't be counted).

        // HOWEVER, to ensure the user has "answered" every question, we need to track that.
        // So we will store { qId, answer: type } OR { qId, answer: null }.

        const answerValue = isSelected ? type : null;

        setAnswers(prev => {
            const existingIndex = prev.findIndex(a => a.qId === qId);
            if (existingIndex >= 0) {
                const newAnswers = [...prev];
                newAnswers[existingIndex] = { qId, answer: answerValue };
                return newAnswers;
            } else {
                return [...prev, { qId, answer: answerValue }];
            }
        });
    };

    const handleNextPage = () => {
        // Validate that all questions on this page have an answer (even if it's "Not Me" / null)
        const currentQ = questions.slice(currentPage * QUESTIONS_PER_PAGE, (currentPage + 1) * QUESTIONS_PER_PAGE);
        const allAnswered = currentQ.every(q => answers.some(a => a.qId === q.qId));

        if (!allAnswered) {
            alert("Please answer all questions on this page before proceeding.");
            return;
        }

        window.scrollTo({ top: 0, behavior: 'smooth' });
        setCurrentPage(prev => prev + 1);
    };

    const handleSubmit = async () => {
        // Validate current page
        const currentQ = questions.slice(currentPage * QUESTIONS_PER_PAGE, (currentPage + 1) * QUESTIONS_PER_PAGE);
        const allAnswered = currentQ.every(q => answers.some(a => a.qId === q.qId));

        if (!allAnswered) {
            alert("Please answer all questions on this page before submitting.");
            return;
        }

        if (isSubmitting.current || isCompleted) return;
        isSubmitting.current = true;
        setLoading(true);

        try {
            // Filter out null answers (Not Me) to comply with Backend Schema 
            // which requires 'answer' to be a String.
            const validAnswers = answers.filter(a => a.answer !== null);

            if (validAnswers.length === 0) {
                alert("You must select 'Describes Me' for at least one question.");
                setLoading(false);
                isSubmitting.current = false;
                return;
            }

            const userId = getUserId();
            const result = await submitAssessment(userId, setId, validAnswers);
            console.log('Assessment submitted successfully:', result);
            setIsCompleted(true);
        } catch (error) {
            console.error("Failed to submit", error);
            setLoading(false);
            isSubmitting.current = false;
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-black text-white">
                <div className="animate-pulse flex flex-col items-center">
                    <div className="h-12 w-12 border-4 border-cyan-400 border-t-transparent rounded-full animate-spin mb-4"></div>
                    <p className="text-cyan-400 font-mono">
                        {isCompleted ? 'Calculating Results...' : 'Loading System...'}
                    </p>
                </div>
            </div>
        );
    }

    const currentQuestions = questions.slice(currentPage * QUESTIONS_PER_PAGE, (currentPage + 1) * QUESTIONS_PER_PAGE);
    const totalPages = Math.ceil(questions.length / QUESTIONS_PER_PAGE);
    const isLastPage = currentPage === totalPages - 1;

    return (
        <main className="min-h-screen flex flex-col items-center justify-start p-4 md:p-8 bg-black relative text-white">
            {/* Background Particles/Glow */}
            <div className="fixed top-0 left-0 w-full h-full overflow-hidden z-0 pointer-events-none">
                <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-purple-600/20 rounded-full blur-[100px]" />
                <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-cyan-600/20 rounded-full blur-[100px]" />
            </div>

            <div className="z-10 w-full max-w-4xl flex flex-col gap-8">
                <div className="flex flex-col gap-2 mb-4">
                    <ProgressBar current={currentPage + 1} total={totalPages} label={`Page ${currentPage + 1} of ${totalPages}`} />
                    <p className="text-zinc-400 text-sm text-right">
                        Questions {currentPage * QUESTIONS_PER_PAGE + 1} - {Math.min((currentPage + 1) * QUESTIONS_PER_PAGE, questions.length)} of {questions.length}
                    </p>
                </div>

                <div className="space-y-4">
                    {currentQuestions.map((q) => {
                        const existingAnswer = answers.find(a => a.qId === q.qId);
                        // Determine state: true (Describes Me), false (Not Me), undefined (Unanswered)
                        const currentVal = existingAnswer ? existingAnswer.answer : undefined;
                        // Note: currentVal is 'D'/'I'/'S'/'C' or null.
                        // We want to know if it is "Selected" (not null and matches type) OR "Rejected" (null but exists in array)

                        const isSelected = currentVal === q.type;
                        const isRejected = existingAnswer && currentVal === null;

                        return (
                            <div key={q.qId} className="glass-panel p-6 rounded-xl border border-white/10 bg-white/5 hover:bg-white/10 transition-colors">
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                                    <h3 className="text-lg md:text-xl font-light flex-1">{q.question}</h3>

                                    <div className="flex gap-3 shrink-0">
                                        <button
                                            onClick={() => handleAnswer(q.qId, q.type, true)}
                                            className={`px-4 py-2 rounded-lg border transition-all duration-300 ${isSelected
                                                ? 'bg-cyan-500/20 border-cyan-400 text-cyan-300 shadow-[0_0_10px_rgba(34,211,238,0.3)]'
                                                : 'border-white/20 text-zinc-400 hover:border-white/40'
                                                }`}
                                        >
                                            Describes Me
                                        </button>
                                        <button
                                            onClick={() => handleAnswer(q.qId, q.type, false)}
                                            className={`px-4 py-2 rounded-lg border transition-all duration-300 ${isRejected
                                                ? 'bg-red-500/20 border-red-400 text-red-300'
                                                : 'border-white/20 text-zinc-400 hover:border-white/40'
                                                }`}
                                        >
                                            Not Me
                                        </button>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="flex justify-end pt-8 pb-12">
                    {isLastPage ? (
                        <button
                            onClick={handleSubmit}
                            className="px-8 py-4 rounded-xl bg-gradient-to-r from-cyan-600 to-blue-600 text-white font-bold text-lg hover:scale-105 transition-transform shadow-[0_0_20px_rgba(34,211,238,0.5)]"
                        >
                            Complete Assessment
                        </button>
                    ) : (
                        <button
                            onClick={handleNextPage}
                            className="px-8 py-4 rounded-xl bg-white text-black font-bold text-lg hover:scale-105 transition-transform"
                        >
                            Next Page
                        </button>
                    )}
                </div>
            </div>
        </main>
    );
}
